window.calculate=function(e){const a=Number(document.getElementById("a").value),t=Number(document.getElementById("b").value),r=document.getElementById("result");if(!Number.isFinite(a)||!Number.isFinite(t))return void alert("Podaj poprawne liczby w polach A i B.");let i;switch(e){case"+":i=a+t;break;case"-":i=a-t;break;case"*":i=a*t;break;case"/":if(0===t)return void alert("Nie można dzielić przez zero!");i=a/t;break;default:return void alert("Nieznana operacja: "+e)}r.value=String(Math.round(1e10*i)/1e10)};